function bubbleSort(a) {
  for (let i = 0; i < a.length - 1; i++) {
    let swapped = false;
    for (let j = 0; j < a.length - 1 - i; j++) {
      if (a[j] > a[j + 1]) {
        [a[j], a[j + 1]] = [a[j + 1], a[j]];
        swapped = true;
      }
    }
    if (!swapped) break; // already sorted
  }
  return a;
}

function selectionSort(a) {
  for (let i = 0; i < a.length - 1; i++) {
    let min = i;
    for (let j = i + 1; j < a.length; j++) {
      if (a[j] < a[min]) min = j;
    }
    if (min !== i) [a[i], a[min]] = [a[min], a[i]];
  }
  return a;
}

function insertionSort(a) {
  for (let i = 1; i < a.length; i++) {
    const key = a[i];
    let j = i - 1;
    while (j >= 0 && a[j] > key) {
      a[j + 1] = a[j];
      j--;
    }
    a[j + 1] = key;
  }
  return a;
}

function mergeSort(a) {
  if (a.length < 2) return a;
  const mid = Math.floor(a.length / 2);
  const left = mergeSort(a.slice(0, mid));
  const right = mergeSort(a.slice(mid));
  const out = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    out.push(left[i] <= right[j] ? left[i++] : right[j++]);
  }
  return out.concat(left.slice(i)).concat(right.slice(j));
}

function quickSort(a, lo = 0, hi = a.length - 1) {
  if (lo >= hi) return a;
  const pivot = a[hi];
  let i = lo - 1;
  for (let j = lo; j < hi; j++) {
    if (a[j] <= pivot) {
      i++;
      [a[i], a[j]] = [a[j], a[i]];
    }
  }
  [a[i + 1], a[hi]] = [a[hi], a[i + 1]];
  quickSort(a, lo, i);
  quickSort(a, i + 2, hi);
  return a;
}

function heapSort(a) {
  const sink = (n, i) => {
    let big = i;
    const l = 2 * i + 1, r = 2 * i + 2;
    if (l < n && a[l] > a[big]) big = l;
    if (r < n && a[r] > a[big]) big = r;
    if (big !== i) {
      [a[i], a[big]] = [a[big], a[i]];
      sink(n, big);
    }
  };
  for (let i = (a.length >> 1) - 1; i >= 0; i--) sink(a.length, i);
  for (let end = a.length - 1; end > 0; end--) {
    [a[0], a[end]] = [a[end], a[0]];
    sink(end, 0);
  }
  return a;
}

function countingSort(a, k) {
  const counts = new Array(k).fill(0);
  for (const v of a) counts[v]++;
  const out = [];
  for (let v = 0; v < k; v++) {
    for (let c = 0; c < counts[v]; c++) out.push(v);
  }
  return out;
}

function linearSearch(a, target) {
  for (let i = 0; i < a.length; i++) {
    if (a[i] === target) return i;
  }
  return -1;
}

function binarySearch(a, target) {
  let lo = 0, hi = a.length - 1;
  while (lo <= hi) {
    const mid = lo + ((hi - lo) >> 1);
    if (a[mid] === target) return mid;
    if (a[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

function jumpSearch(a, target) {
  const n = a.length;
  const step = Math.floor(Math.sqrt(n));
  let prev = 0, cur = step;
  while (cur < n && a[Math.min(cur, n - 1)] < target) {
    prev = cur;
    cur += step;
  }
  for (let i = prev; i <= Math.min(cur, n - 1); i++) {
    if (a[i] === target) return i;
  }
  return -1;
}

function twoSumSorted(a, target) {
  let lo = 0, hi = a.length - 1;
  while (lo < hi) {
    const sum = a[lo] + a[hi];
    if (sum === target) return [a[lo], a[hi]];
    if (sum < target) lo++;
    else hi--;
  }
  return null;
}

function maxWindowSum(a, k) {
  let sum = 0, best = -Infinity;
  for (let i = 0; i < a.length; i++) {
    sum += a[i];
    if (i >= k) sum -= a[i - k];
    if (i >= k - 1) best = Math.max(best, sum);
  }
  return best;
}

function kadane(a) {
  let cur = 0, best = -Infinity;
  for (const v of a) {
    cur = Math.max(v, cur + v);
    best = Math.max(best, cur);
  }
  return best;
}

function naiveSearch(text, pat) {
  for (let i = 0; i + pat.length <= text.length; i++) {
    let j = 0;
    while (j < pat.length && text[i + j] === pat[j]) j++;
    if (j === pat.length) return i;
  }
  return -1;
}

function buildLps(pat) {
  const lps = new Array(pat.length).fill(0);
  let len = 0;
  for (let i = 1; i < pat.length; ) {
    if (pat[i] === pat[len]) lps[i++] = ++len;
    else if (len > 0) len = lps[len - 1];
    else lps[i++] = 0;
  }
  return lps;
}

function kmp(text, pat) {
  const lps = buildLps(pat);
  let i = 0, j = 0;
  while (i < text.length) {
    if (text[i] === pat[j]) { i++; j++; if (j === pat.length) return i - j; }
    else if (j > 0) j = lps[j - 1];
    else i++;
  }
  return -1;
}

function isPalindrome(s) {
  let lo = 0, hi = s.length - 1;
  while (lo < hi) {
    if (s[lo] !== s[hi]) return false;
    lo++;
    hi--;
  }
  return true;
}

