function isValid(s) {
  const pairs = { ')': '(', ']': '[', '}': '{' };
  const stack = [];
  for (const ch of s) {
    if (ch === '(' || ch === '[' || ch === '{') stack.push(ch);
    else if (stack.pop() !== pairs[ch]) return false;
  }
  return stack.length === 0;
}

function nextGreater(a) {
  const res = new Array(a.length).fill(-1);
  const stack = [];
  for (let i = 0; i < a.length; i++) {
    while (stack.length && a[stack[stack.length - 1]] < a[i]) {
      res[stack.pop()] = a[i];
    }
    stack.push(i);
  }
  return res;
}

class MinStack {
  constructor() {
    this.data = [];
    this.mins = [];
  }
  push(v) {
    this.data.push(v);
    this.mins.push(this.mins.length ? Math.min(v, this.getMin()) : v);
  }
  pop() {
    this.mins.pop();
    return this.data.pop();
  }
  getMin() {
    return this.mins[this.mins.length - 1];
  }
}

class Queue {
  constructor() {
    this.items = [];
    this.head = 0;
  }
  enqueue(v) { this.items.push(v); }
  dequeue() {
    if (this.head >= this.items.length) return undefined;
    return this.items[this.head++]; // O(1), no re-indexing
  }
  peek() { return this.items[this.head]; }
  get size() { return this.items.length - this.head; }
}

class CircularQueue {
  constructor(k) {
    this.buf = new Array(k);
    this.cap = k;
    this.head = 0;
    this.tail = 0;
    this.size = 0;
  }
  enqueue(v) {
    if (this.size === this.cap) return false;
    this.buf[this.tail] = v;
    this.tail = (this.tail + 1) % this.cap;
    this.size++;
    return true;
  }
  dequeue() {
    if (this.size === 0) return undefined;
    const v = this.buf[this.head];
    this.head = (this.head + 1) % this.cap;
    this.size--;
    return v;
  }
}

function maxSlidingWindow(a, k) {
  const dq = []; // indices, values decreasing
  const out = [];
  for (let i = 0; i < a.length; i++) {
    while (dq.length && dq[0] <= i - k) dq.shift();
    while (dq.length && a[dq[dq.length - 1]] <= a[i]) dq.pop();
    dq.push(i);
    if (i >= k - 1) out.push(a[dq[0]]);
  }
  return out;
}

function insertAfter(node, value) {
  const fresh = { value, next: node.next };
  node.next = fresh;
  return fresh;
}

function traverse(head) {
  const out = [];
  for (let cur = head; cur !== null; cur = cur.next) {
    out.push(cur.value);
  }
  return out;
}

function reverseList(head) {
  let prev = null;
  let curr = head;
  while (curr !== null) {
    const next = curr.next; // save first
    curr.next = prev;
    prev = curr;
    curr = next;
  }
  return prev; // new head
}

function hasCycle(head) {
  let slow = head, fast = head;
  while (fast !== null && fast.next !== null) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}

function inorder(node, out = []) {
  if (!node) return out;
  inorder(node.left, out);
  out.push(node.value);
  inorder(node.right, out);
  return out;
}

function preorder(node, out = []) {
  if (!node) return out;
  out.push(node.value);
  preorder(node.left, out);
  preorder(node.right, out);
  return out;
}

function postorder(node, out = []) {
  if (!node) return out;
  postorder(node.left, out);
  postorder(node.right, out);
  out.push(node.value);
  return out;
}

function levelOrder(root) {
  if (!root) return [];
  const queue = [root];
  const out = [];
  while (queue.length) {
    const node = queue.shift();
    out.push(node.value);
    if (node.left) queue.push(node.left);
    if (node.right) queue.push(node.right);
  }
  return out;
}

function search(node, key) {
  while (node) {
    if (key === node.value) return node;
    node = key < node.value ? node.left : node.right;
  }
  return null;
}

function insert(node, key) {
  if (!node) return { value: key, left: null, right: null };
  if (key < node.value) node.left = insert(node.left, key);
  else if (key > node.value) node.right = insert(node.right, key);
  return node;
}

class MaxHeap {
  constructor() { this.a = []; }
  push(v) {
    this.a.push(v);
    let i = this.a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.a[p] >= this.a[i]) break;
      [this.a[p], this.a[i]] = [this.a[i], this.a[p]];
      i = p;
    }
  }
  peek() { return this.a[0]; }
}

pop() {
  const top = this.a[0];
  const last = this.a.pop();
  if (this.a.length) {
    this.a[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = 2 * i + 2;
      let big = i;
      if (l < this.a.length && this.a[l] > this.a[big]) big = l;
      if (r < this.a.length && this.a[r] > this.a[big]) big = r;
      if (big === i) break;
      [this.a[i], this.a[big]] = [this.a[big], this.a[i]];
      i = big;
    }
  }
  return top;
}

function topK(nums, k) {
  const heap = new MinHeap();
  for (const n of nums) {
    if (heap.size < k) heap.push(n);
    else if (n > heap.peek()) { heap.pop(); heap.push(n); }
  }
  return heap.toArray().sort((a, b) => b - a);
}

function bfs(adj, start) {
  const queue = [start];
  const seen = new Set([start]);
  const order = [];
  while (queue.length) {
    const node = queue.shift();
    order.push(node);
    for (const next of adj[node]) {
      if (!seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }
  return order;
}

function dfs(adj, node, seen = new Set(), order = []) {
  seen.add(node);
  order.push(node);
  for (const next of adj[node]) {
    if (!seen.has(next)) dfs(adj, next, seen, order);
  }
  return order;
}

function dijkstra(adj, weights, source) {
  const dist = {};
  for (const node in adj) dist[node] = Infinity;
  dist[source] = 0;
  const settled = new Set();
  while (settled.size < Object.keys(adj).length) {
    let best = null;
    for (const n in dist) {
      if (!settled.has(n) && (best === null || dist[n] < dist[best])) best = n;
    }
    if (best === null || dist[best] === Infinity) break;
    settled.add(best);
    for (const nb of adj[best]) {
      const cand = dist[best] + weights[best + '-' + nb];
      if (cand < dist[nb]) dist[nb] = cand;
    }
  }
  return dist;
}

function topoSort(adj) {
  const indeg = {};
  for (const n in adj) indeg[n] = indeg[n] || 0;
  for (const n in adj) for (const m of adj[n]) indeg[m] = (indeg[m] || 0) + 1;
  const queue = Object.keys(indeg).filter((n) => indeg[n] === 0);
  const order = [];
  while (queue.length) {
    const node = queue.shift();
    order.push(node);
    for (const next of adj[node]) {
      if (--indeg[next] === 0) queue.push(next);
    }
  }
  return order.length === Object.keys(adj).length ? order : null; // null = cycle
}

class Trie {
  constructor() { this.root = { children: {}, end: false }; }
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children[ch]) node.children[ch] = { children: {}, end: false };
      node = node.children[ch];
    }
    node.end = true;
  }
}

search(word) {
  let node = this.root;
  for (const ch of word) {
    node = node.children[ch];
    if (!node) return false;
  }
  return node.end;
}

function autocomplete(trie, prefix) {
  let node = trie.root;
  for (const ch of prefix) {
    node = node.children[ch];
    if (!node) return [];
  }
  const out = [];
  (function collect(n, acc) {
    if (n.end) out.push(acc);
    for (const ch in n.children) collect(n.children[ch], acc + ch);
  })(node, prefix);
  return out;
}

class HashMap {
  constructor(size = 7) { this.slots = new Array(size).fill(null); }
  _hash(key) {
    let h = 0;
    for (const ch of String(key)) h = (h * 31 + ch.charCodeAt(0)) % this.slots.length;
    return h;
  }
  set(key, value) {
    let i = this._hash(key);
    while (this.slots[i] && this.slots[i][0] !== key) i = (i + 1) % this.slots.length;
    this.slots[i] = [key, value];
  }
  get(key) {
    let i = this._hash(key);
    while (this.slots[i]) {
      if (this.slots[i][0] === key) return this.slots[i][1];
      i = (i + 1) % this.slots.length;
    }
    return undefined;
  }
}

function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  }
  return null;
}

function frequencies(items) {
  const counts = new Map();
  for (const item of items) counts.set(item, (counts.get(item) ?? 0) + 1);
  return counts;
}

function isAnagram(a, b) {
  if (a.length !== b.length) return false;
  const counts = new Map();
  for (const ch of a) counts.set(ch, (counts.get(ch) ?? 0) + 1);
  for (const ch of b) {
    if (!counts.get(ch)) return false;
    counts.set(ch, counts.get(ch) - 1);
  }
  return true;
}

function spiralOrder(m) {
  const out = [];
  let top = 0, bottom = m.length - 1, left = 0, right = m[0].length - 1;
  while (top <= bottom && left <= right) {
    for (let c = left; c <= right; c++) out.push(m[top][c]);
    top++;
    for (let r = top; r <= bottom; r++) out.push(m[r][right]);
    right--;
    if (top <= bottom) { for (let c = right; c >= left; c--) out.push(m[bottom][c]); bottom--; }
    if (left <= right) { for (let r = bottom; r >= top; r--) out.push(m[r][left]); left++; }
  }
  return out;
}

function rotate(m) {
  const n = m.length;
  for (let r = 0; r < n; r++)
    for (let c = r + 1; c < n; c++)
      [m[r][c], m[c][r]] = [m[c][r], m[r][c]];
  for (const row of m) row.reverse();
  return m;
}

function numIslands(grid) {
  const rows = grid.length, cols = grid[0].length;
  const seen = grid.map(r => r.map(() => false));
  let count = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== 1 || seen[r][c]) continue;
      count++;
      const stack = [[r, c]];
      seen[r][c] = true;
      while (stack.length) {
        const [cr, cc] = stack.pop();
        for (const [dr, dc] of [[1,0],[-1,0],[0,1],[0,-1]]) {
          const nr = cr + dr, nc = cc + dc;
          if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) continue;
          if (grid[nr][nc] !== 1 || seen[nr][nc]) continue;
          seen[nr][nc] = true;
          stack.push([nr, nc]);
        }
      }
    }
  }
  return count;
}

function factorial(n) {
  if (n <= 1) return 1;      // base case
  return n * factorial(n - 1); // recursive case
}

// exponential
function fib(n) {
  if (n < 2) return n;
  return fib(n - 1) + fib(n - 2);
}

// linear, same recursion plus a cache
function fibMemo(n, memo = new Map()) {
  if (n < 2) return n;
  if (memo.has(n)) return memo.get(n);
  const value = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  memo.set(n, value);
  return value;
}

function hanoi(n, from, to, via, moves = []) {
  if (n === 0) return moves;
  hanoi(n - 1, from, via, to, moves);
  moves.push(`disk ${n}: ${from} -> ${to}`);
  hanoi(n - 1, via, to, from, moves);
  return moves;
}

function mergeSort(a) {
  if (a.length < 2) return a;               // divide
  const mid = a.length >> 1;
  const left = mergeSort(a.slice(0, mid));  // conquer
  const right = mergeSort(a.slice(mid));
  const out = [];                           // combine
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    out.push(left[i] <= right[j] ? left[i++] : right[j++]);
  }
  return out.concat(left.slice(i), right.slice(j));
}

function binarySearch(a, target, lo = 0, hi = a.length - 1) {
  if (lo > hi) return -1;
  const mid = (lo + hi) >> 1;
  if (a[mid] === target) return mid;
  return a[mid] < target
    ? binarySearch(a, target, mid + 1, hi)
    : binarySearch(a, target, lo, mid - 1);
}

function maxSubarray(a, lo = 0, hi = a.length - 1) {
  if (lo === hi) return a[lo];
  const mid = (lo + hi) >> 1;
  const left = maxSubarray(a, lo, mid);
  const right = maxSubarray(a, mid + 1, hi);
  let sum = 0, bestL = -Infinity, bestR = -Infinity;
  for (let i = mid; i >= lo; i--) { sum += a[i]; bestL = Math.max(bestL, sum); }
  sum = 0;
  for (let i = mid + 1; i <= hi; i++) { sum += a[i]; bestR = Math.max(bestR, sum); }
  return Math.max(left, right, bestL + bestR);
}

function solveNQueens(n) {
  const board = Array.from({ length: n }, () => new Array(n).fill('.'));
  const cols = new Set(), d1 = new Set(), d2 = new Set();
  const place = (row) => {
    if (row === n) return true;
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || d1.has(row - c) || d2.has(row + c)) continue;
      board[row][c] = 'Q';
      cols.add(c); d1.add(row - c); d2.add(row + c);
      if (place(row + 1)) return true;
      board[row][c] = '.';                         // undo
      cols.delete(c); d1.delete(row - c); d2.delete(row + c);
    }
    return false;
  };
  return place(0) ? board : null;
}

