function subsets(nums) {
  const out = [], current = [];
  const walk = (i) => {
    if (i === nums.length) { out.push([...current]); return; }
    current.push(nums[i]);   // choose
    walk(i + 1);
    current.pop();           // un-choose
    walk(i + 1);
  };
  walk(0);
  return out;
}

function solveMaze(maze) {
  const n = maze.length, path = [];
  const inside = (r, c) => r >= 0 && c >= 0 && r < n && c < maze[0].length;
  const walk = (r, c, seen = new Set()) => {
    const id = r + ',' + c;
    if (!inside(r, c) || maze[r][c] === 0 || seen.has(id)) return false;
    seen.add(id);
    path.push([r, c]);
    if (r === n - 1 && c === maze[0].length - 1) return true;
    if (walk(r + 1, c, seen) || walk(r, c + 1, seen) ||
        walk(r, c - 1, seen) || walk(r - 1, c, seen)) return true;
    path.pop();                 // backtrack
    return false;
  };
  return walk(0, 0) ? path : null;
}

function fibTab(n) {
  if (n < 2) return n;
  const dp = [0, 1];
  for (let i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];
  return dp[n];
}

// O(1) space version
function fibFast(n) {
  let a = 0, b = 1;
  for (let i = 0; i < n; i++) [a, b] = [b, a + b];
  return a;
}

function knapsack(weights, values, cap) {
  const n = weights.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(cap + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    for (let w = 0; w <= cap; w++) {
      dp[i][w] = dp[i - 1][w]; // skip
      if (weights[i - 1] <= w) {
        dp[i][w] = Math.max(dp[i][w], values[i - 1] + dp[i - 1][w - weights[i - 1]]);
      }
    }
  }
  return dp[n][cap];
}

function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      dp[i][j] = a[i - 1] === b[j - 1]
        ? dp[i - 1][j - 1] + 1
        : Math.max(dp[i - 1][j], dp[i][j - 1]);
    }
  }
  return dp[a.length][b.length];
}

function coinChange(coins, amount) {
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0;
  for (let x = 1; x <= amount; x++) {
    for (const coin of coins) {
      if (coin <= x) dp[x] = Math.min(dp[x], dp[x - coin] + 1);
    }
  }
  return dp[amount] === Infinity ? -1 : dp[amount];
}

function selectActivities(items) {
  const sorted = [...items].sort((a, b) => a.end - b.end);
  const out = [];
  let lastEnd = -Infinity;
  for (const a of sorted) {
    if (a.start >= lastEnd) { out.push(a); lastEnd = a.end; }
  }
  return out;
}

function greedyChange(coins, amount) {
  const used = [];
  for (const coin of [...coins].sort((a, b) => b - a)) {
    while (amount >= coin) { amount -= coin; used.push(coin); }
  }
  return amount === 0 ? used : null;
}

function fractionalKnapsack(items, cap) {
  const sorted = [...items].sort((a, b) => b.value / b.weight - a.value / a.weight);
  let total = 0;
  for (const it of sorted) {
    if (cap <= 0) break;
    const take = Math.min(it.weight, cap);
    total += (it.value * take) / it.weight;
    cap -= take;
  }
  return total;
}

const getBit    = (n, k) => (n >> k) & 1;
const setBit    = (n, k) => n | (1 << k);
const clearBit  = (n, k) => n & ~(1 << k);
const toggleBit = (n, k) => n ^ (1 << k);
const isEven    = (n) => (n & 1) === 0;
const isPowerOf2 = (n) => n > 0 && (n & (n - 1)) === 0;

function popcount(n) {
  let count = 0;
  while (n) {
    n &= n - 1; // clear the lowest set bit
    count++;
  }
  return count;
}

const lowestSetBit = (n) => n & -n;

function singleNumber(nums) {
  let x = 0;
  for (const n of nums) x ^= n;
  return x;
}

function missingNumber(nums) {
  let x = nums.length;
  for (let i = 0; i < nums.length; i++) x ^= i ^ nums[i];
  return x;
}
